// Request client tests (generated by engineering-platform frontend-auth asset)
import { describe, it, expect, beforeEach, vi } from 'vitest';
import { configureRequestClient, http, ApiError } from '../src/api/request';

describe('request client', () => {
  let getToken: () => string | null;
  let onUnauthorized: ReturnType<typeof vi.fn>;

  beforeEach(() => {
    getToken = () => 'tok-1';
    onUnauthorized = vi.fn();
    configureRequestClient({ getToken, onUnauthorized });
    vi.restoreAllMocks();
  });

  it('injects Authorization Bearer header', async () => {
    const fetchMock = vi.fn().mockResolvedValue({
      ok: true,
      status: 200,
      json: async () => ({ success: true, data: { ok: true }, error: null, message: null }),
    });
    vi.stubGlobal('fetch', fetchMock);

    await http.get<{ ok: boolean }>('/products');

    const [, init] = fetchMock.mock.calls[0];
    expect((init as RequestInit).headers).toMatchObject({ Authorization: 'Bearer tok-1' });
  });

  it('401 triggers onUnauthorized and throws ApiError', async () => {
    vi.stubGlobal('fetch', vi.fn().mockResolvedValue({
      ok: false,
      status: 401,
      json: async () => ({ success: false, data: null, error: { code: 'UNAUTHENTICATED', message: 'auth required' }, message: null }),
    }));

    await expect(http.get('/x')).rejects.toBeInstanceOf(ApiError);
    expect(onUnauthorized).toHaveBeenCalled();
  });

  it('403 maps to ApiError without logout', async () => {
    vi.stubGlobal('fetch', vi.fn().mockResolvedValue({
      ok: false,
      status: 403,
      json: async () => ({ success: false, data: null, error: { code: 'PERMISSION_DENIED', message: 'denied' }, message: null }),
    }));

    const error: unknown = await http.get('/x').catch((e) => e);
    expect(error).toBeInstanceOf(ApiError);
    expect((error as ApiError).code).toBe('PERMISSION_DENIED');
    expect(onUnauthorized).not.toHaveBeenCalled();
  });

  it('maps backend error code/message', async () => {
    vi.stubGlobal('fetch', vi.fn().mockResolvedValue({
      ok: false,
      status: 400,
      json: async () => ({ success: false, data: null, error: { code: 'PRODUCT_CODE_DUPLICATE', message: 'dup' }, message: null }),
    }));

    const error: unknown = await http.post('/products', {}).catch((e) => e);
    expect(error).toBeInstanceOf(ApiError);
    expect((error as ApiError).code).toBe('PRODUCT_CODE_DUPLICATE');
    expect((error as ApiError).message).toBe('dup');
  });
});
